import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    try:
        marks = int(data[0])
    except:
        # If not an integer, just exit
        return

    if marks >= 90:
        grade = "A"
    elif marks >= 75:
        grade = "B"
    elif marks >= 50:
        grade = "C"
    else:
        grade = "Fail"
    sys.stdout.write(grade)

if __name__ == "__main__":
    solve()
